function parseUiCopyTable(rows) {
const copy2 = {};
rows.trim().split("\n").map((row) => row.replace(/^ +/u, "")).forEach((row) => {
const tab = row.indexOf("	");
if (tab < 0) {
const key = row.trim();
if (key) copy2[key] = "";
return;
}
if (tab === 0) return;
copy2[row.slice(0, tab)] = row.slice(tab + 1).replaceAll("{APP_NAME}", APP_NAME);
});
return copy2;
}
